inline bool IsShell(uint32_t id)
{
    std::size_t low = 0, high = sizeof(ShellIds) / sizeof(ShellIds[0]);
    while (low < high)
    {
        std::size_t const mid = (low + high) / 2;
        if (ShellIds[mid] == id)
            return true;
        if (ShellIds[mid] < id)
            low = mid + 1;
        else
            high = mid;
    }
    return false;
}
